import{_ as d,o as e,c as o,a5 as a}from"./chunks/framework.CsGesDJn.js";const T=JSON.parse('{"title":"Test — Deactivate Account","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-9-deactivate-account/test.md","filePath":"feature/authentication/3-2-9-deactivate-account/test.md"}'),c={name:"feature/authentication/3-2-9-deactivate-account/test.md"};function r(n,t,h,s,i,u){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="test-—-deactivate-account" tabindex="-1">Test — Deactivate Account <a class="header-anchor" href="#test-—-deactivate-account" aria-label="Permalink to &quot;Test — Deactivate Account&quot;">​</a></h1><h2 id="flow-a-—-user-co-password" tabindex="-1">Flow A — User có password <a class="header-anchor" href="#flow-a-—-user-co-password" aria-label="Permalink to &quot;Flow A — User có password&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Mô tả</th><th>AC/Edge</th><th>Kết quả mong đợi</th><th>Trạng thái</th></tr></thead><tbody><tr><td>TC-01</td><td>Deactivate password đúng</td><td>AC &quot;set status=DEACTIVATED&quot;</td><td>200, soft-delete (không xóa cứng)</td><td>Chưa test</td></tr><tr><td>TC-02</td><td>Password sai</td><td>Error &quot;WRONG_CURRENT_PASSWORD&quot;</td><td>400 <code>WRONG_CURRENT_PASSWORD</code></td><td>Chưa test</td></tr><tr><td>TC-03</td><td>Owner Agency active</td><td>Edge &quot;Owner duy nhất Agency&quot;</td><td>409 <code>AGENCY_OWNERSHIP_ACTIVE</code>, không deactivate</td><td>Chưa test</td></tr><tr><td>TC-04</td><td>Login sau deactivate</td><td>AC &quot;không login được&quot;</td><td>403 <code>ACCOUNT_DEACTIVATED</code></td><td>Chưa test</td></tr><tr><td>TC-05</td><td>Dữ liệu liên quan còn trong DB</td><td>AC &quot;giữ dữ liệu&quot;</td><td>User/Agency/Workspace record vẫn tồn tại</td><td>Chưa test</td></tr><tr><td>TC-06</td><td>Agency chỉ còn SOFT_DELETED/INACTIVE</td><td>Edge &quot;không còn agency active&quot;</td><td>200, cho deactivate</td><td>Chưa test</td></tr><tr><td>TC-07</td><td>Deactivate lại user đã deactivated</td><td>Edge &quot;idempotent&quot;</td><td>400 <code>WRONG_CURRENT_PASSWORD</code> (re-match password)</td><td>Chưa test</td></tr><tr><td>TC-07b</td><td><strong>MỚI</strong>: Deactivate thành công → accessToken + refreshToken bị blacklist</td><td>AC &quot;blacklist token&quot; (BR-22)</td><td>Cả 2 token gọi lại API/refresh đều bị từ chối ngay lập tức (không cần đợi expire/refresh lần sau)</td><td>Chưa test</td></tr></tbody></table><h2 id="flow-b-—-user-oauth-only-otp-—-moi" tabindex="-1">Flow B — User OAuth-only (OTP) — MỚI <a class="header-anchor" href="#flow-b-—-user-oauth-only-otp-—-moi" aria-label="Permalink to &quot;Flow B — User OAuth-only (OTP) — MỚI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Mô tả</th><th>AC/Edge</th><th>Kết quả mong đợi</th><th>Trạng thái</th></tr></thead><tbody><tr><td>TC-08</td><td><code>send-otp</code> thành công</td><td>AC &quot;nhận OTP qua email&quot;</td><td>200, Redis có key <code>otp:deactivate:{userId}</code> TTL~10 phút, email gửi đi</td><td>Chưa test</td></tr><tr><td>TC-09</td><td><code>send-otp</code> thiếu/sai Bearer token</td><td>Error &quot;INVALID_CREDENTIALS&quot;</td><td>401 <code>INVALID_CREDENTIALS</code></td><td>Chưa test</td></tr><tr><td>TC-10</td><td><code>deactivate</code> với OTP đúng (đã gọi send-otp trước)</td><td>AC &quot;set status=DEACTIVATED&quot;</td><td>200, soft-delete, Redis key bị xóa</td><td>Chưa test</td></tr><tr><td>TC-11</td><td><code>deactivate</code> với OTP sai</td><td>Error &quot;OTP_INVALID&quot;</td><td>400 <code>OTP_INVALID</code></td><td>Chưa test</td></tr><tr><td>TC-12</td><td><code>deactivate</code> với OTP hết hạn (&gt;10 phút)</td><td>Error &quot;OTP_INVALID&quot;</td><td>400 <code>OTP_INVALID</code></td><td>Chưa test</td></tr><tr><td>TC-13</td><td><code>deactivate</code> không gửi <code>otpCode</code>, hoặc chưa từng gọi <code>send-otp</code></td><td>Error &quot;OTP_INVALID&quot;</td><td>400 <code>OTP_INVALID</code></td><td>Chưa test</td></tr><tr><td>TC-14</td><td><code>deactivate</code> dùng lại OTP đã verify thành công trước đó</td><td>Edge &quot;OTP dùng 1 lần&quot;</td><td>400 <code>OTP_INVALID</code> (key đã bị xóa)</td><td>Chưa test</td></tr><tr><td>TC-15</td><td>User OAuth-only là Owner Agency active</td><td>Edge &quot;Owner duy nhất Agency&quot; (Flow B)</td><td>409 <code>AGENCY_OWNERSHIP_ACTIVE</code>, không deactivate, OTP đã bị xóa (không tái sử dụng)</td><td>Chưa test</td></tr><tr><td>TC-16</td><td>Login sau deactivate (Flow B)</td><td>AC &quot;không login được&quot;</td><td>403 <code>ACCOUNT_DEACTIVATED</code></td><td>Chưa test</td></tr></tbody></table><h2 id="regression-—-đam-bao-2-flow-khong-lan-nhau" tabindex="-1">Regression — đảm bảo 2 flow không lẫn nhau <a class="header-anchor" href="#regression-—-đam-bao-2-flow-khong-lan-nhau" aria-label="Permalink to &quot;Regression — đảm bảo 2 flow không lẫn nhau&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Mô tả</th><th>AC/Edge</th><th>Kết quả mong đợi</th><th>Trạng thái</th></tr></thead><tbody><tr><td>TC-17</td><td>User có password gửi <code>otpCode</code> thay vì <code>password</code></td><td>Edge &quot;field sai flow bị bỏ qua&quot;</td><td>400 <code>WRONG_CURRENT_PASSWORD</code> (BE vẫn theo nhánh password vì <code>passwordHash != null</code>)</td><td>Chưa test</td></tr><tr><td>TC-18</td><td>User OAuth-only gửi <code>password</code> thay vì <code>otpCode</code></td><td>Edge &quot;field sai flow bị bỏ qua&quot;</td><td>400 <code>OTP_INVALID</code> (BE vẫn theo nhánh OTP vì <code>passwordHash == null</code>)</td><td>Chưa test</td></tr></tbody></table>',7)])])}const C=d(c,[["render",r]]);export{T as __pageData,C as default};
